attempts.rawText:
{
  "layer1": "⑤는 ㉠이 주체와 대상을 미리 나눠 놓았다고 짚은 데까지는 맞아. 하지만 (나)의 필자는 지각 뒤에 둘이 정해진다고 보므로, ㉠은 타당하지 않다고 평가해.",
  "symbolGlosses": [
    {
      "symbol": "㉠",
      "gloss": "인지 과정은 주체와 통합되어야 성립한다는 주장"
    },
    {
      "symbol": "(나)",
      "gloss": "지각 이후 주체와 대상이 확정된다고 보는 글"
    }
  ],
  "pair": {
    "top": "주체와 대상의 분리를 통해서만 지각이 이루어질 수 있다고 보는 것",
    "source": "다시 말해 주체와 대상은 지각이 일어난 이후 비로소 확정된다.",
    "sourceFocus": "지각이 일어난 이후 비로소 확정된다",
    "conclusion": "(나)의 필자에게 주체는 지각 전에 정해져 있지 않으므로, 이미 정해진 인지 주체를 전제한 주장은 타당하지 않아.",
    "sourceFocus": "지각이 일어난 이후 비로소 확정된다"
  },
  "examinerIntent": "⑤는 주체와 대상을 미리 나누는 생각을 (나)의 필자가 비판하는데도, 그 생각에 동의하는 것처럼 ‘타당하다’고 붙였어.",
  "selfCheckOptions": [
    "(나)의 필자도 주체와 대상이 먼저 나뉘어 있어야 지각할 수 있다고 읽었어.",
    "⑤의 앞부분이 맞다고 보고 ‘타당하다’까지 맞다고 골랐어.",
    "(나)의 필자가 아니라 로랜즈의 설명과 맞는지를 따졌어."
  ]
}
